import{_ as a}from"./chunks/20-cli-doctor.DOzHD6qf.js";import{_ as s,o as i,c as t,a2 as o}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"التثبيت","description":"","frontmatter":{},"headers":[],"relativePath":"ar/guide/installation.md","filePath":"ar/guide/installation.md"}'),n={name:"ar/guide/installation.md"};function l(r,e,d,h,p,c){return i(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="التثبيت" tabindex="-1">التثبيت <a class="header-anchor" href="#التثبيت" aria-label="Permalink to &quot;التثبيت&quot;">​</a></h1><p>انسخ المستودع (<code>git clone https://github.com/TerminalDZ/vidcreat.git</code>) أو فك ضغط أرشيف إصدار في أي مكان تريده (مثل <code>Documents/ReelForge</code>). وللحصول على تصدير أسرع، تجنّب المجلدات التي يزامنها OneDrive أو iCloud.</p><h2 id="على-windows-10-و11" tabindex="-1">على Windows 10 و11 <a class="header-anchor" href="#على-windows-10-و11" aria-label="Permalink to &quot;على Windows 10 و11&quot;">​</a></h2><ol><li>ثبّت <strong>Node.js 22 LTS</strong> من <a href="https://nodejs.org" target="_blank" rel="noreferrer">https://nodejs.org</a> (مع الإعدادات الافتراضية). إن لم يكن مثبتاً، يستطيع المثبّت تثبيته عبر <code>winget</code>.</li><li>انقر مرتين على <strong><code>install.bat</code></strong>. سيتولى ما يلي: <ul><li>التحقق من Node.js،</li><li>عرض تثبيت <strong>ffmpeg</strong> عبر <code>winget</code> (أجب بـ <strong>Y</strong>)،</li><li>تثبيت اعتماديات ReelForge،</li><li>تنزيل إصدار Chromium المحدَّد الذي يُستخدم في التصدير،</li><li>تشغيل فحص كامل للبيئة.</li></ul></li><li>انقر مرتين على <strong><code>start.bat</code></strong> لفتح لوحة التحكم.</li></ol><blockquote><p>إذا حذّرك Windows SmartScreen من السكربت، اختر <strong>More info ← Run anyway</strong>. وإذا ثُبّت ffmpeg للتو، أغلق <code>start.bat</code> وأعد فتحه حتى يتعرف Windows على قيمة PATH الجديدة.</p></blockquote><h2 id="على-macos" tabindex="-1">على macOS <a class="header-anchor" href="#على-macos" aria-label="Permalink to &quot;على macOS&quot;">​</a></h2><ol><li><p>ثبّت <strong>Node.js 22 LTS</strong> من <a href="https://nodejs.org" target="_blank" rel="noreferrer">https://nodejs.org</a> و<strong>Homebrew</strong> من <a href="https://brew.sh" target="_blank" rel="noreferrer">https://brew.sh</a>.</p></li><li><p>افتح <strong>Terminal</strong> داخل مجلد ReelForge (من Finder: انقر بالزر الأيمن على المجلد ثم <em>New Terminal at Folder</em>) وشغّل:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span></span></code></pre></div><p>أجب بـ <strong>Y</strong> عندما يعرض عليك تشغيل <code>brew install ffmpeg</code>.</p></li><li><p>انقر مرتين على <strong><code>ReelForge.command</code></strong> (أو شغّل <code>./start.sh</code>) لفتح لوحة التحكم.</p></li></ol><h2 id="على-linux" tabindex="-1">على Linux <a class="header-anchor" href="#على-linux" aria-label="Permalink to &quot;على Linux&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./install.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # add --yes to accept every prompt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # opens the dashboard</span></span></code></pre></div><p>يستخدم المثبّت مدير الحزم لديك (<code>apt</code> أو <code>dnf</code> أو <code>pacman</code> أو <code>zypper</code>) لتثبيت ffmpeg، ويستطيع تثبيت مكتبات النظام التي يحتاجها Chromium (سيطلب صلاحية <code>sudo</code>).</p><h2 id="من-المصدر-للمطورين" tabindex="-1">من المصدر (للمطورين) <a class="header-anchor" href="#من-المصدر-للمطورين" aria-label="Permalink to &quot;من المصدر (للمطورين)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/TerminalDZ/vidcreat.git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vidcreat</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span></span></code></pre></div><p>يشرح <a href="./contributing.html">دليل المساهمة</a> إعداد بيئة التطوير الكاملة على كل نظام.</p><h2 id="افحص-الإعداد-في-أي-وقت" tabindex="-1">افحص الإعداد في أي وقت <a class="header-anchor" href="#افحص-الإعداد-في-أي-وقت" aria-label="Permalink to &quot;افحص الإعداد في أي وقت&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Windows: reelforge.cmd doctor</span></span></code></pre></div><p>يفحص الأمر Node.js وffmpeg (الإصدار والمرمّزات والمرشحات) وChromium والخطوط المضمّنة، ويطبع الإصلاح الدقيق لكل ما ينقص. وتعرض لوحة التحكم الفحص نفسه في مؤشر الحالة بالشريط العلوي.</p><p><img src="`+a+`" alt="الأمر reelforge doctor"></p><h2 id="نماذج-الكلام-الاختيارية" tabindex="-1">نماذج الكلام الاختيارية <a class="header-anchor" href="#نماذج-الكلام-الاختيارية" aria-label="Permalink to &quot;نماذج الكلام الاختيارية&quot;">​</a></h2><p>تعمل المحاذاة التلقائية للـ cues دون أي تنزيل (بكشف فترات التوقف في الكلام ومطابقتها مع النص المعروف). وللحصول على دقة على مستوى الكلمة مع وجود موسيقى في الخلفية، ثبّت نماذج الكلام الاختيارية مرة واحدة (نحو 180 MB):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --setup</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # downloads Whisper and Silero VAD into your user cache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reelforge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> align</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # shows what is installed</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">حل المشكلات <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;حل المشكلات {#troubleshooting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>العَرَض</th><th>الحل</th></tr></thead><tbody><tr><td>تعرض لوحة التحكم “setup issues”</td><td>انقر على المؤشر: يعرض كل فحص فاشل طريقة إصلاحه. السبب الأكثر شيوعاً غياب ffmpeg.</td></tr><tr><td>الرسالة <code>ffmpeg not found</code></td><td>على Windows: <code>winget install Gyan.FFmpeg</code>، وعلى macOS: <code>brew install ffmpeg</code>، وعلى Linux: مدير الحزم. ثم افتح طرفية جديدة أو <code>start.bat</code>.</td></tr><tr><td>الرسالة “Cannot launch Chromium”</td><td>شغّل <code>reelforge doctor --fix</code>. وعلى Linux أعد تشغيل المثبّت ووافق على تثبيت مكتبات النظام.</td></tr><tr><td>لا يُعثر على ffmpeg رغم تثبيته (Windows)</td><td>أغلق كل الطرفيات و<code>start.bat</code> ثم أعد فتحها: لا يقرأ Windows قيمة PATH الجديدة إلا في النوافذ الجديدة.</td></tr><tr><td>الأمر <code>pnpm</code> غير معروف</td><td>شغّل <code>corepack enable</code> مرة واحدة (يأتي Corepack مع Node.js 22)، ثم افتح طرفية جديدة.</td></tr><tr><td>التصدير بطيء أو يفشل بأخطاء القرص</td><td>انقل المجلد خارج OneDrive أو iCloud واترك نحو 2 GB متاحة للملفات المؤقتة.</td></tr></tbody></table><p>تجد إجابات أخرى في <a href="./faq.html">أسئلة شائعة وحل المشكلات</a>.</p><h2 id="التحديث" tabindex="-1">التحديث <a class="header-anchor" href="#التحديث" aria-label="Permalink to &quot;التحديث&quot;">​</a></h2><p>إذا نسخت المستودع، شغّل <code>git pull</code> ثم أعد تشغيل المثبّت (أو <code>pnpm install &amp;&amp; pnpm build</code>).</p><p>إذا نزّلت أرشيف إصدار، نزّل الإصدار الجديد من <a href="https://github.com/TerminalDZ/vidcreat/releases" target="_blank" rel="noreferrer">صفحة الإصدارات</a>، وفك ضغطه بجانب القديم، وانسخ مجلد <code>episodes/</code> (وأي <code>themes/</code> أو <code>presets/</code> خاصة بك) إلى المجلد الجديد، ثم شغّل المثبّت مجدداً. حلقاتك ملفات عادية، فلا شيء آخر يحتاج إلى ترحيل.</p><h2 id="إلغاء-التثبيت" tabindex="-1">إلغاء التثبيت <a class="header-anchor" href="#إلغاء-التثبيت" aria-label="Permalink to &quot;إلغاء التثبيت&quot;">​</a></h2><p>احذف مجلد ReelForge. أما Chromium المنزَّل فيوجد في مجلد التخزين المؤقت (cache) الخاص بالمستخدم (<code>%LOCALAPPDATA%\\ms-playwright</code> على Windows، و<code>~/Library/Caches/ms-playwright</code> على macOS، و<code>~/.cache/ms-playwright</code> على Linux)، ويمكن حذفه أيضاً. وتوجد نماذج الكلام الاختيارية التي يثبّتها الأمر <code>reelforge align --setup</code> في المجلد <code>reelforge</code> داخل مجلد التخزين المؤقت نفسه (<code>%LOCALAPPDATA%\\reelforge</code> و<code>~/Library/Caches/reelforge</code> و<code>~/.cache/reelforge</code>).</p>`,28)])])}const u=s(n,[["render",l]]);export{m as __pageData,u as default};
